#!/usr/bin/env python3
from pathlib import Path
import json,hashlib,pandas as pd,numpy as np
from pyproj import Transformer
H=Path(__file__).resolve().parent;ROOT=H.parents[2];P=ROOT/'maps/cycle06_access_v2_directed_timebands'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
ledger=pd.read_parquet(P/'np_point_timebands.parquet');targets=pd.read_parquet(P/'selected_targets.parquet');manifest=json.loads((P/'map_figure_manifest.json').read_text());checks=[]
def check(s,v):checks.append(dict(check=s,pass_=bool(v)));assert v,s
actual=ledger.groupby(['target_id','native2021_frame','route_status'],dropna=False).size().rename('n_NP').reset_index();saved=pd.read_csv(P/'coverage_by_status.csv');check('every_status_denominator',actual.sort_values(['target_id','native2021_frame','route_status']).reset_index(drop=True).equals(saved.sort_values(['target_id','native2021_frame','route_status']).reset_index(drop=True)))
actual=ledger[ledger.time_band_code.ge(0)].groupby(['target_id','native2021_frame','time_band_minutes'],observed=True).size().rename('n_NP').reset_index();saved=pd.read_csv(P/'coverage_by_timeband.csv');actual.time_band_minutes=actual.time_band_minutes.astype(str);check('every_band_denominator',actual.sort_values(['target_id','native2021_frame','time_band_minutes']).reset_index(drop=True).equals(saved.sort_values(['target_id','native2021_frame','time_band_minutes']).reset_index(drop=True)))
figures=manifest['figures']
for target in targets.to_dict('records'):
 data=ledger[ledger.target_id.eq(target['id'])];proj=Transformer.from_crs('EPSG:4326',f"+proj=aeqd +lat_0={target['lat']} +lon_0={target['lon']} +datum=WGS84 +units=m",always_xy=True);x,y=proj.transform(data.lon.to_numpy(float),data.lat.to_numpy(float));native=data.native2021_frame.to_numpy();plot=native&data.coordinates_available.to_numpy()&np.isfinite(x)&np.isfinite(y)&(abs(x)<=900000)&(abs(y)<=900000);known=native&data.directed_total_minutes.notna().to_numpy();entry=next(v for v in figures if v['target_id']==target['id']);check('source_counts_visible_figure:'+target['name'],entry['native2021_origins']==native.sum() and entry['native2021_recorded_routes']==known.sum() and entry['native2021_recorded_routes_plotted']==(known&plot).sum() and entry['native2021_recorded_routes_outside_panel_or_without_coordinates']==(known&~plot).sum())
outputs=[P/f'{i:02d}_directed_np_timebands.png' for i in range(1,5)]
receipt=dict(status='FOUR_ACTUAL_PNG_FIGURES_VISUALLY_AND_SOURCE_DENOMINATOR_ACCEPTED',all_checks_passed=True,n_checks=len(checks),n_failed=0,checks=checks,visually_viewed_all_four_actual_PNG=True,observations=['Russian titles, axes, native frame counts and complete legend are readable; no cropped titles/legend/footnotes.','Arrows/title explicitly say NP origin toward anchor; no reverse-route assumption.','Eight discrete point time bands, gray unknown bounded route and orange rejected snap remain distinguishable.','Footnotes identify January2021 road scenario,15kmh connectors, no observed trips, no continuous surface and context role for Moscow/SPB.','Native2021 frame and coordinate missingness counts are not national complete source coverage claims.'],visual_outputs_sha256={p.name:sha(p) for p in outputs},map_freeze_manifest_sha256=sha(P/'freeze_manifest.json'),map_figure_manifest_sha256=sha(P/'map_figure_manifest.json'),code_sha256=sha(Path(__file__)))
(H/'map_visual_and_coverage_admission.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');print(len(checks))
